16	 */
17	final class DtoMapper {
18	
19	    private DtoMapper() {
20	    }
21	
22	    /** 十进制输出：去掉多余尾零，零统一输出 "0"。 */
23	    static String format(BigDecimal value) {
24	        BigDecimal stripped = value.stripTrailingZeros();
25	        if (stripped.compareTo(BigDecimal.ZERO) == 0) {
26	            return "0";
27	        }
28	        return stripped.toPlainString();
29	    }
