        mvc.perform(post("/api/measurements/drift").contentType(MediaType.APPLICATION_JSON)
                        .content(driftJson("REQ-D20", "D-9", "INS-D", "2026-06-01T10:30:00Z",
                                "5", "0", "9", t0, t1)))
                .andExpect(status().isUnprocessableEntity());

